package com.yuvro.todo.controller;

import com.yuvro.todo.entity.Task;
import com.yuvro.todo.entity.User;
import com.yuvro.todo.repository.TaskRepository;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;

import java.util.*;

@RestController
@RequestMapping("/api/tasks")
public class TaskController {

    private final TaskRepository taskRepository;

    public TaskController(TaskRepository taskRepository) {
        this.taskRepository = taskRepository;
    }

    private User getAuthenticatedUser(Authentication authentication) {
        if (authentication != null && authentication.getPrincipal() instanceof User user) {
            return user;
        }
        return null;
    }

    @PostMapping
    public ResponseEntity<Map<String, Object>> createTask(
            Authentication authentication,
            @RequestBody(required = false) Map<String, Object> body) {
        User currentUser = getAuthenticatedUser(authentication);
        if (currentUser == null) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
                    .body(Collections.singletonMap("error", "Authorization token is missing or invalid"));
        }

        if (body == null || !body.containsKey("title")) {
            return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                    .body(Collections.singletonMap("error", "Title is required"));
        }

        String title = body.get("title") != null ? body.get("title").toString().trim() : "";
        if (title.isEmpty()) {
            return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                    .body(Collections.singletonMap("error", "Title is required"));
        }

        String description = body.get("description") != null ? body.get("description").toString() : "";

        Task task = new Task(currentUser, title, description);
        task = taskRepository.save(task);

        Map<String, Object> response = new HashMap<>();
        response.put("message", "Task created successfully");
        response.put("task", task.toDict());
        return ResponseEntity.status(HttpStatus.CREATED).body(response);
    }
}

